ex items-center justify-between text-xs text-[#F6F3EC]/70 mt-2\"><span class=\"inline-flex items-center gap-1 text-[11px] font-semibold text-[#D8C7A1] group-hover:translate-x-1 transition-transform\">Explore &rarr;</span></div></div></div></a><?php endforeach; ?>"; file_put_contents("products.php", substr($c, 0, $s) . $r . substr($c, $e)); echo "Done"; } else { echo "Not found bounds."; } ?>
